import { defineRouteMiddleware } from "@astrojs/starlight/route-data";

// Per-page Open Graph image (generated by src/pages/og/[...slug].png.ts).
export const onRequest = defineRouteMiddleware((context) => {
  const { head, id } = context.locals.starlightRoute;
  const base = import.meta.env.BASE_URL.replace(/\/$/, "");
  const url = new URL(`${base}/og/${id.replace(/\/index$/, "") || "index"}.png`, context.site).href;
  head.push({ tag: "meta", attrs: { property: "og:image", content: url } });
  head.push({ tag: "meta", attrs: { name: "twitter:card", content: "summary_large_image" } });
});
